<script setup lang="ts">
import {onMounted,ref} from 'vue';import {apiFetch,clearCsrf,type SessionUser} from '../api';
const props=defineProps<{originId:string,destinationId:string}>();const emit=defineEmits<{user:[SessionUser|null]}>();
const user=ref<SessionUser|null>(null),mode=ref<'login'|'register'|'recovery'>('login'),email=ref(''),password=ref(''),name=ref(''),message=ref(''),error=ref(''),busy=ref(false),favorites=ref<Array<{id:string;label:string;originId:string;destinationId:string}>>([]),favoriteLabel=ref('Meu trajeto');
async function loadSession(){try{user.value=await (await apiFetch('/api/me')).json();emit('user',user.value)}catch{user.value=null;emit('user',null);return}try{await loadFavorites()}catch(e){error.value=e instanceof Error?e.message:'A sessão está ativa, mas os favoritos não puderam ser carregados.'}}
async function submit(){busy.value=true;error.value='';message.value='';try{if(mode.value==='recovery'){await apiFetch('/api/auth/recovery',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email.value})});message.value='Se a conta existir, as instruções foram enviadas para o ambiente de e-mail configurado.';return}if(mode.value==='register')await apiFetch('/api/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email.value,name:name.value,password:password.value})});const body=new URLSearchParams({username:email.value,password:password.value});await apiFetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});clearCsrf();await loadSession();message.value='Sessão iniciada com segurança.'}catch(e){error.value=e instanceof Error?e.message:'Não foi possível entrar.'}finally{busy.value=false}}
async function logout(){busy.value=true;error.value='';message.value='';try{await apiFetch('/api/auth/logout',{method:'POST'});clearCsrf();user.value=null;favorites.value=[];emit('user',null);message.value='Sessão encerrada.'}catch(e){error.value=e instanceof Error?e.message:'Não foi possível sair.'}finally{busy.value=false}}
async function loadFavorites(){favorites.value=await (await apiFetch('/api/favorites')).json()}
async function addFavorite(){busy.value=true;error.value='';message.value='';try{await apiFetch('/api/favorites',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({originId:props.originId,destinationId:props.destinationId,label:favoriteLabel.value})});await loadFavorites();message.value='Favorito salvo como intenção de trajeto; ele será recalculado ao abrir.'}catch(e){error.value=e instanceof Error?e.message:'Não foi possível salvar.'}finally{busy.value=false}}
async function removeFavorite(id:string){busy.value=true;error.value='';message.value='';try{await apiFetch(`/api/favorites/${id}`,{method:'DELETE'});await loadFavorites()}catch(e){error.value=e instanceof Error?e.message:'Não foi possível remover.'}finally{busy.value=false}}
onMounted(loadSession)
</script>
<template><section id="account" class="workspace-panel" aria-labelledby="account-title"><header><div><h2 id="account-title">{{ user?'Sua conta':'Entrar no OinbuPebas' }}</h2><p>{{ user?'Favoritos são intenções e sempre usam horários atualizados.':'Sua sessão fica em cookie protegido; nenhuma credencial vai para o armazenamento local.' }}</p></div><button v-if="user" class="secondary" :disabled="busy" @click="logout">Sair</button></header><p v-if="message" class="success-message" role="status">{{ message }}</p><p v-if="error" class="inline-error" role="alert">{{ error }}</p><div v-if="!user" class="account-layout"><form @submit.prevent="submit"><div class="segmented" role="group" aria-label="Ação de conta"><button type="button" :aria-pressed="mode==='login'" @click="mode='login'">Entrar</button><button type="button" :aria-pressed="mode==='register'" @click="mode='register'">Criar conta</button><button type="button" :aria-pressed="mode==='recovery'" @click="mode='recovery'">Recuperar</button></div><label for="account-email">E-mail</label><input id="account-email" v-model="email" type="email" autocomplete="email" required><template v-if="mode==='register'"><label for="account-name">Nome</label><input id="account-name" v-model="name" autocomplete="name" minlength="2" required></template><template v-if="mode!=='recovery'"><label for="account-password">Senha</label><input id="account-password" v-model="password" type="password" :autocomplete="mode==='register'?'new-password':'current-password'" minlength="10" required></template><button class="primary" :disabled="busy">{{ busy?'Processando…':mode==='login'?'Entrar':mode==='register'?'Criar e entrar':'Enviar instruções' }}</button></form></div><div v-else class="favorites-layout"><div><strong>{{ user.name }}</strong><span>{{ user.email }} · {{ user.role }}</span></div><form class="favorite-form" @submit.prevent="addFavorite"><label for="favorite-label">Nome do favorito</label><input id="favorite-label" v-model="favoriteLabel" maxlength="100" required><button class="primary" :disabled="busy">Salvar busca atual</button></form><div><h3>Favoritos salvos</h3><p v-if="!favorites.length" class="empty-copy">Você ainda não salvou trajetos.</p><ul class="plain-list"><li v-for="favorite in favorites" :key="favorite.id"><span><strong>{{ favorite.label }}</strong><small>{{ favorite.originId }} → {{ favorite.destinationId }}</small></span><button class="text-action" :disabled="busy" @click="removeFavorite(favorite.id)">Remover</button></li></ul></div></div></section></template>
